"""Phase 14 (2026-11-23 reconciliation): put the audit caveats INTO the operative rule text that a production agent reads (column `rule`).
Keeps the pre-edit text in `rule_text_prior_v3` and records Codex's independent verdict and the reconciliation response per rule.
usage: python3 -I scripts/phase14_rule_operative_update.py   (idempotent; backup of the v3 ledger is written once)"""
import csv, os, shutil
A = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
F = A + '/knowledge_base_draft/RULE_EVIDENCE_LEDGER.csv'
BK = A + '/knowledge_base_draft/RULE_EVIDENCE_LEDGER_v3_2026-11-23_before_reconcile.csv'
if not os.path.exists(BK): shutil.copy(F, BK)
rows = list(csv.DictReader(open(BK)))
# new operative text per rule (None = unchanged). Each states sample, selection and limits inside the rule itself.
NEW = {
'K01': "Of the 43 long scripts that have a transcript (a census, not a sample), 41 to 42 open with a viewer-attributed question (41 by audit label, 42 by regex; exceptions V019, V024). That the script then reframes the question in beat 2 is a playbook RECOMMENDATION from reading, not a measured rate. One channel, no contrast set, no performance data.",
'K02': "In the script text of 41 of 43 long videos no call-to-action wording was found (V019 has a book promo, V020 action wording). Separately, a red book-promo end card closes 44 of 44 long videos and 0 of 24 Shorts examined (length about 10 s, measured on 20 long only); the card is itself a book CTA, so 'no CTA' applies to the script text only. Established channel with an existing audience: not evidence for a new channel.",
'K03': "Newer long scripts are shorter: median 632 words against 825 for older ones (21 vs 22 long videos, a post-hoc temporal split; one of six metrics tested, Bonferroni-adjusted p about 0.05). The cause is unexplained and there is no retention data; use as a reference only.",
'K04': "Words per TOTAL second (script words divided by total video duration, so pauses and the end card are included; not an articulation rate): median 3.59 for 43 long videos, 3.57 vs 3.63 across eras. Catalog and ASR text are provisional.",
'K05': "38 of 40 scripted Shorts are re-cuts of a long script (8-gram containment >= 0.30, median 0.895, parents in 28 families); V065 and V080 have no parent. Contiguity of the excerpt and excerpt-versus-abridgement were not measured.",
'K06': "AUDIO ENERGY above -45 dB begins within 0.5 s of the file start in 88 of 88 media files (median 0.06 s, max 0.49 s; waveform only, so it cannot tell narrator from music or effects). The first ASR segment time of 0.00 s is a Whisper artefact, NOT evidence of when speech starts; speech onset is UNVERIFIED until someone listens. The first machine-detected visual event lands at a median of 1.8 s (campaign ledgers) and 2.0 s (audit ledgers), a detector-dependent figure.",
'K07': "Machine-detected visual events (not reviewed events) occur about every 2.1 s, 20 to 23 per minute, in two disjoint sets of 44 videos that use two different detectors; faint-layer events (1,585 long + 204 Short) are excluded.",
'K08': "Shot (hard-cut span) median: 8.44 s in the campaign ledgers (24 long) and 6.75 s with the audit detector (20 long); the two are not pooled and Brain's 7.77 s is another unit. Because 37 of 156 reviewed boundaries were not true cuts (K22), shot counts are overstated and spans understated; always state the detector and sample.",
'K09': "Under the frame-difference threshold used, about 93 to 94% of frames are visual holds (long median 93.2 over 44, Short 94.1 over 44; the ledger had written 93.3). Threshold-dependent: 12 of 88 videos are below 80%, two continuous-motion videos at 31% and 55%.",
'K10': "In 125 purpose-selected quantity-moment frames (82 videos; not a random draw) the palette is mostly achromatic (dark line on near-white, or white on near-black) with a sparing red accent (red above 0.05% of pixels in 39 of 125, 31%). DOCUMENTED EXCEPTIONS: map and heat scenes use flat colour fills or gradients (WH4g1ptJ-70 green, tan and blue; gp5G1QG6cXc 162 s red-orange); in 160 frames from ten episodes 20 (12.5%) have more than 5% chromatic pixels, 9 of them in the rotated-world episode; red also fills series title cards and the end card. The share of coloured scenes across the whole channel is unknown.",
'K11': "Thin-stroke width, a pixel measurement on the same 125 purpose-selected frames: median 6.32 px for long (n=63) and 5.66 px for Short (n=31) at a 1080 px short side, measuring only skeleton points with local radius <= 8 px and EXCLUDING silhouette frames (more than half the ink is filled area; 30 frames excluded, 1 frame had no measurable skeleton). Without the exclusion the long median is 6.0 (n=86). Error +-1 to 2 px; describes line-art frames only.",
'K12': "Negative space (share of 48-px grid cells with no non-background pixel): median 0.66 long and 0.77 Short over 125 purpose-selected frames (not random); full-bleed map and gradient frames are low.",
'K13': "BASE NARRATOR FIGURE ONLY: empty ring head, single-line body; height over head diameter median 3.46 (IQR 3.23 to 3.58, n=28 from a ring-detection heuristic, checked by eye on 24 frames). Other characters occur (child with hair, reporter, helmeted figure, hat figure, cat, others) and poses and expressions were not coded.",
'K14': "In 125 frames chosen at quantity moments (stills, one same-model coder) the spoken number was restated on screen in 53 of 105 non-NA frames (50.5%; long 53%, Short 46%), partly in 24 more. Not a random draw; the ten-episode pass is not comparable.",
'K15': "A numeral or unit label beside the drawing is the commonest quantity device (one code per frame in 125 frames, one coder): LABEL alone 38; 46 when equations and titles are grouped with it; mechanism diagram 30 when MECH and SCENE are grouped. Comparisons ride on layout (side-by-side, axis, bracket).",
'K16': "Camera-like moves DO occur (pan, zoom and sideways scroll, often with motion blur, mostly over maps and in diagram transitions: 15 of 16 shots flagged from stills were confirmed in 0.25 s-step frame sequences of 6 videos, 16 shots, `14_MOTION_SEQUENCE_16_CODING.csv`), but their FREQUENCY across the channel is unmeasured. Event-type shares (scene swap about 19.7% of 2,022 long events; 686 Short events) come from an earlier labelling pass not re-verified, so do not claim that visual change is mostly cuts, pop-ons or write-ons rather than camera moves. Durations are bounded only to <= 0.5 to 1.25 s by the 0.25 s sampling.",
'K17': "Machine association, not listening: 56% of ASR clause starts (4,439 segments, 88 videos) have a machine-detected visual event within 0.5 s, against 33 to 37% under time shifts (about 20 points). ASR timings are provisional and the direction of influence is unknown.",
'K18': "Mix loudness is about -16.5 LUFS (median; 84 of 88 files within -17.5 to -15.5) and silences of 0.35 s or more below -50 dB are rare (median 0.28% of duration, max 1.9%); machine measurements that say nothing about voice, music or effects quality (not listened).",
'K19': "Recompute every spoken physical number before reuse. Of 10 checked claims (self-selected, same-model recomputation, partial Codex re-check of 4; no expert review): 4 consistent, 2 with a caveat, 2 qualified (SC02 growing Earth: 5.953 g at constant density against a literal 'over 6 g'; SC05 magnitude 25: result flips with the energy-magnitude relation, toy extrapolation), 1 open (lightning 'two days': definitions and original source required), 1 not verified. In the ten-episode pass the laser's 5 PW versus 'double world electricity' is a wording discrepancy in the source (about 1,900 to 2,250x, not 2x) whose units need the authors' confirmation.",
'K20': "No 3D RENDERING was observed in the viewed stills and in 16 short frame sequences (0.25 s steps), where depth cues were 2D pan, zoom, blur and scale-down through nested drawings, and no multi-plane parallax was identified; but sampled stills and 16 sequences cannot establish the absence of 3D, parallax or depth animation anywhere in the channel. Hand-drawn perspective objects are present (E10 swing ride 154 s, a house at E01 14.9 s, slanted rails at E08 232 s) and glow or gradient effects appear (E09, E05, E01). Do not state for production that the series uses or avoids 3D or parallax.",
'K21': "RECOMMENDATION (untested in production; 10 scenes): pick the animation method from the scientific idea and the story function, cheapest sufficient method first.",
'K22': "DESCRIPTIVE FINDING for a purpose-built review sample, not a channel rate: of 156 reviewed shots (stratified by format x boundary strength, unequal sampling fractions 14% to 53%, clustered by video with median 3 and maximum 9 shots per video, one same-model coder) 119 (76% of the sample) were true cuts, 33 false progressive changes, 4 borderline. In the sample strength < 0.3 gave 50 of 77 and strength >= 0.3 gave 69 of 79. A post-stratified estimate of 78% with a video-cluster bootstrap of 72% to 85% is a sensitivity figure only (selection prioritised videos with fewer sampled shots, so random-within-stratum is not met). Camera moves over maps, slides, counter changes and overlays cause false boundaries. This is a precision-type finding; recall (missed real cuts) is not estimated.",
'K23': None,
}
CODEX = {'K01':'UNRESOLVED','K02':'UNRESOLVED','K03':'UNRESOLVED','K04':'UNRESOLVED','K05':'UNRESOLVED','K06':'UNSUPPORTED (F02)','K07':'UNRESOLVED','K08':'UNRESOLVED','K09':'UNRESOLVED','K10':'QUALIFIED (F03)','K11':'UNRESOLVED','K12':'UNRESOLVED','K13':'UNRESOLVED','K14':'UNRESOLVED','K15':'UNRESOLVED','K16':'UNSUPPORTED (F03/K16)','K17':'UNRESOLVED','K18':'UNRESOLVED','K19':'UNRESOLVED','K20':'QUALIFIED (F03)','K21':'UNRESOLVED','K22':'QUALIFIED (F07)','K23':'POLICY'}
RESP = {'K19':'AGREE with F05/F11: SC02 -> QUALIFIED; E09g discrepancy recorded without guessing intent', 'K06':'AGREE: operative text rewritten; speech onset UNVERIFIED','K10':'AGREE: exceptions moved into operative text','K20':'AGREE: 3D/parallax absence not claimed','K16':'AGREE with F03 direction, then tested: 15 of 16 camera-move inferences confirmed in dense sequences; frequency still unmeasured','K22':'AGREE: descriptive, design-aware sensitivity only, recall not inferred','K11':'PARTIAL: exclusion made explicit; n corrected 93 -> 94 (63 long + 31 Short)'}
out = []
for r in rows:
    k = r['rule_id']; r['rule_text_prior_v3'] = r['rule']
    if NEW.get(k): r['rule'] = NEW[k]
    r['operative_text_status'] = 'REVISED_2026-11-23_RECONCILE' if NEW.get(k) else 'UNCHANGED'
    r['codex_independent_verdict_2026-11-23'] = CODEX[k]
    r['reconcile_response'] = RESP.get(k, 'wording checked against sample, selection and limits; sample limits now in the rule text' if NEW.get(k) else 'checked; no change needed')
    if k == 'K22': r['audit_label_2026_11_23'] = 'SUPPORTED WITHIN SAMPLE (descriptive)'; r['coverage'] = '156 of 675 eligible shots (23%); 563 of 719 not reviewed, of which 44 are first shots with no boundary'
    if k == 'K06': r['class'] = 'MEASURED (audio energy); speech onset UNVERIFIED'; r['audit_label_2026_11_23'] = 'QUALIFIED'
    if k == 'K11': r['coverage'] = '94 of 125 frames (63 long + 31 Short; silhouettes excluded)'
    if k == 'K20': r['class'] = 'OBSERVED (stills only); absence of 3D/parallax NOT established'
    if k == 'K16': r['class'] = 'UNMEASURED (camera motion); event labels INHERITED'
    out.append(r)
w = csv.DictWriter(open(F, 'w', newline=''), fieldnames=list(out[0])); w.writeheader(); w.writerows(out)
print(sum(1 for r in out if r['operative_text_status'] != 'UNCHANGED'), 'rules revised of', len(out))
